const out = [];
for (let i = 0; i < 10; i++) {
  if (window.__ensemble.getState().settings.onboarded) break;
  const all = [...document.querySelectorAll('button')].filter(b => !b.disabled);
  const find = re => all.find(b => re.test(b.textContent.trim()));
  const b = find(/^(Continue|Start using|Start with|Get started|Start working|Done|Finish|Open Ensemble)/) || find(/^Skip/);
  if (!b) break;
  out.push(b.textContent.trim().slice(0, 30));
  b.click();
  await new Promise(r => setTimeout(r, 900));
}
return 'clicked: ' + out.join(' > ');

const st = window.__ensemble;
window.__u = { chatId: st.getState().chatId, agents: null, tasks: null };
const U = window.__u;
const apply = () => st.setState(s => {
  const out = {};
  out.chats = s.chats.map(c => {
    if (c.id !== U.chatId) return c;
    let n = c;
    if (!c.ultra) n = { ...n, ultra: true };
    if (U.agents && !U.agents.every(a => (c.agents || []).some(x => x.id === a.id))) n = { ...n, agents: [...(c.agents || []).filter(x => !U.agents.some(a => a.id === x.id)), ...U.agents] };
    return n;
  });
  if (U.agents && U.agents.some(a => !s.members[a.id])) out.members = { ...s.members, ...Object.fromEntries(U.agents.map(a => [a.id, a])) };
  if (U.tasks) {
    const cur = s.tasks[U.chatId] || [];
    if (!U.tasks.every(t => cur.some(x => x.id === t.id))) out.tasks = { ...s.tasks, [U.chatId]: [...cur.filter(x => !U.tasks.some(t => t.id === x.id)), ...U.tasks] };
  }
  return out;
});
U.apply = apply;
st.subscribe(s => { const c = s.chats.find(c => c.id === U.chatId); if (!c) return; const miss = !c.ultra || (U.agents && U.agents.some(a => !s.members[a.id])) || (U.agents && !U.agents.every(a => (c.agents || []).some(x => x.id === a.id))) || (U.tasks && !U.tasks.every(t => (s.tasks[U.chatId] || []).some(x => x.id === t.id))); if (miss) setTimeout(apply, 0); });
apply();
return 'ultra on for ' + U.chatId;

const st = window.__ensemble; const U = window.__u; const s = st.getState(); const now = Date.now();
const lead = s.chats.find(c => c.id === U.chatId).leadId || s.settings.leadId || s.accounts.find(a => a.enabled).id;
U.lead = lead;
const ALL = [
  ['scout-2', 'Scout 2', lead, 1, 'teal', 'Pricing of five rivals'],
  ['scout-3', 'Scout 3', lead, 1, 'blue', 'Checkout patterns'],
  ['scout-4', 'Scout 4', lead, 1, 'violet', 'Payment provider docs'],
  ['builder-a', 'Builder A', lead, 1, 'clay', 'Version A of the page'],
  ['judge', 'Judge', lead, 1, 'slate', 'Scores every version'],
  ['scout-5', 'Scout 5', lead, 1, 'green', 'Accessibility rules'],
  ['scout-6', 'Scout 6', lead, 1, 'amber', 'Tax and VAT'],
  ['scout-7', 'Scout 7', lead, 1, 'rose', 'Annual discounts'],
  ['scout-8', 'Scout 8', lead, 1, 'slate', 'Conversion studies'],
  ['scout-9', 'Scout 9', lead, 1, 'teal', 'Refund policies'],
  ['scout-10', 'Scout 10', lead, 1, 'blue', 'Trial lengths'],
  ['scout-11', 'Scout 11', lead, 1, 'violet', 'Plan naming'],
  ['scout-12', 'Scout 12', lead, 1, 'green', 'Enterprise tiers'],
  ['builder-b', 'Builder B', lead, 1, 'blue', 'Version B of the page'],
  ['builder-c', 'Builder C', lead, 1, 'violet', 'Version C of the page'],
  ['judge-2', 'Judge 2', lead, 1, 'slate', 'Second scoring pass'],
  ['tester', 'Tester', 'builder-a', 2, 'green', 'Runs the checkout tests'],
  ['reviewer', 'Reviewer', 'builder-a', 2, 'rose', 'Reads the diff cold'],
  ['renderer', 'Renderer', 'builder-b', 2, 'amber', 'Renders each direction'],
  ['critic', 'Critic', 'builder-c', 2, 'clay', 'Checks it against the brief'],
];
window.__grow = (n) => {
  const list = ALL.slice(0, n).map(([id, name, by, depth, accent, role]) => ({ id, name, provider: 'claude', accent, enabled: true, role, spawned: { chatId: U.chatId, base: lead, by, depth, at: now } }));
  const tasks = list.map((a, i) => ({ id: 'ft-' + a.id, chatId: U.chatId, title: a.role, brief: a.role, from: a.spawned.by, to: a.id, status: i % 4 === 0 ? 'done' : i % 4 === 3 ? 'queued' : 'running', createdAt: now - 60000, startedAt: now - 40000 }));
  U.agents = list; U.tasks = tasks; U.apply();
  const busy = list.filter((a, i) => i % 4 === 1 || i % 4 === 2);
  const acts = ['Reading the WCAG checklist', 'Searching the web', 'Writing src/pages/Pricing.tsx', 'Comparing three layouts', 'Reading stripe.com/docs', 'Running the checkout tests'];
  st.setState(x => ({ agents: { ...x.agents, ...Object.fromEntries(busy.map((a, i) => [U.chatId + ':' + a.id, { chatId: U.chatId, accountId: a.id, phase: i === 2 ? 'waiting' : 'thinking', activity: i === 2 ? 'Wants to run npm install' : acts[i % acts.length], queued: 0, turnStartedAt: now - 30000 }])) } }));
  // What the lead's transcript shows: the agents joining, then the work handed out, in one go.
  const k = U.chatId + ':' + lead;
  const mine = list.filter(a => a.spawned.by === lead);
  const fresh = mine.filter(a => !(st.getState().items[k] || []).some(i => i.id === 'fs-' + a.id));
  const items = [
    ...fresh.map((a, i) => ({ id: 'fs-' + a.id, ts: now + i, kind: 'spawn', agentId: a.id, name: a.name, role: a.role, base: lead })),
    ...fresh.map((a, i) => ({ id: 'fd-' + a.id, ts: now + 100 + i, kind: 'delegate', taskId: 'ft-' + a.id, to: a.id, title: a.role, brief: a.role })),
  ];
  st.setState(x => ({ items: { ...x.items, [k]: [...(x.items[k] || []), ...items] } }));
  return 'members now ' + (5 + list.length) + ', busy fake ' + busy.length;
};
return 'grow ready';
